-- 07-events.sql
--
-- EXTRACTED VERBATIM from artifacts/v1/gaos-arcadedb-model.html, which is the
-- source of truth for this schema. Do not edit this file to change the model:
-- change the document, then re-extract. A deviation that lives only here is a
-- schema nobody reviewing the model document would ever see.
--
-- Applied in filename order by deploy/schema/apply.sh. Every statement carries
-- IF NOT EXISTS, so applying twice is a no-op rather than an error.

-- Event is a DOCUMENT type, not a vertex. It has no traversal role: it is
-- always read by (entityId, ts) or by (tenantId, seq). Making it a vertex
-- would add edge-list overhead to the highest-volume type in the database.

-- seq is a monotonic per-tenant counter. ts alone is not enough: two events
-- in the same millisecond must still fold in a deterministic order, which is
-- the "order-stable" requirement from architecture §08.

CREATE DOCUMENT TYPE Event IF NOT EXISTS BUCKETS 16;
CREATE PROPERTY Event.id         STRING   (mandatory true, notnull true);
CREATE PROPERTY Event.tenantId   STRING   (mandatory true, notnull true);
CREATE PROPERTY Event.seq        LONG     (mandatory true, notnull true, min 0);
CREATE PROPERTY Event.type       STRING   (mandatory true, notnull true);
CREATE PROPERTY Event.entityId   STRING   (mandatory true, notnull true);
CREATE PROPERTY Event.entityType STRING   (notnull true);
CREATE PROPERTY Event.actor      STRING;   -- agent id, user id, or 'system'
CREATE PROPERTY Event.payload    MAP;
CREATE PROPERTY Event.ts         DATETIME (mandatory true, notnull true);

-- Snapshot is an optimisation. uptoSeq says exactly which events are already
-- folded into it, so the delta is unambiguous and a corrupt snapshot can
-- always be discarded in favour of a fold from genesis.
CREATE DOCUMENT TYPE Snapshot IF NOT EXISTS;
CREATE PROPERTY Snapshot.id      STRING   (mandatory true, notnull true);
CREATE PROPERTY Snapshot.scope   STRING   (mandatory true, notnull true,
                 regexp 'workflow|task|meeting|floor');
CREATE PROPERTY Snapshot.scopeId STRING   (mandatory true, notnull true);
CREATE PROPERTY Snapshot.uptoSeq LONG     (mandatory true, notnull true);
CREATE PROPERTY Snapshot.state   MAP;
CREATE PROPERTY Snapshot.ts      DATETIME (mandatory true);

-- Time series: cost, latency, room occupancy, queue depth.
-- dims holds the labels you would slice by in Grafana.
CREATE DOCUMENT TYPE Sample IF NOT EXISTS BUCKETS 8;
CREATE PROPERTY Sample.id     STRING   (mandatory true, notnull true);
CREATE PROPERTY Sample.series STRING   (mandatory true, notnull true);
CREATE PROPERTY Sample.value  DOUBLE   (mandatory true, notnull true);
CREATE PROPERTY Sample.ts     DATETIME (mandatory true, notnull true);
CREATE PROPERTY Sample.dims   MAP;
